 1	final class KruskalSolver {
 2	    MstResult compute(Graph graph) {
 3	        DisjointSet disjointSet = new DisjointSet(graph.vertexCount());
 4	        MstState state = new MstState();
 5	
 6	        for (Edge edge : graph.edgesSortedByWeight()) {
 7	            if (!disjointSet.union(edge.from(), edge.to())) {
 8	                continue;
 9	            }
10	
11	            state.include(edge);
12	
13	            if (state.edgesUsed() == graph.requiredEdgeCount()) {
14	                return state.toResult();
15	            }
16	        }
17	
18	        MstResult result = state.toResult();
19	        graph.validateSpanningTree(result);
20	        return result;
21	    }
22	
23	    private static final class MstState {
24	        private int totalWeight;
25	        private int edgesUsed;
26	
27	        private void include(Edge edge) {
28	            totalWeight += edge.weight();
29	            edgesUsed++;
30	        }
31	
32	        private int edgesUsed() {
33	            return edgesUsed;
34	        }
35	
36	        private MstResult toResult() {
37	            return new MstResult(totalWeight, edgesUsed);
38	        }
39	    }
40	}

